function setMooTraceEntry(){
  const label=mooDetail.querySelector('.moo-product-name small');
  label.className='courage-trace-label';
  label.textContent='TRACE YOUR MILK';
}
function resetCourageTrace(){
  mooDetail.removeAttribute('data-trace');
  mooDetail.querySelector('.courage-trace')?.remove();
}
function showCourageTrace(view='photos'){
  const family=Number(mooDetail.dataset.family),config=mooTraceFamilies[family];
  if(!config)return;
  const subject=String(family+1).padStart(2,'0'),info=mooDetail.querySelector('.moo-info');
  const photos=info.querySelectorAll('.moo-field-images img');
  const sourceLabel=info.querySelector('.moo-field-images figcaption').textContent;
  const conditioning=info.querySelector('.moo-source-card>section>p:not(.moo-kicker)').textContent;
  const modification=info.querySelector('.moo-milk-change>p:not(.moo-kicker)').textContent;
  resetCourageTrace();
  mooDetail.dataset.trace=view;
  const panel=document.createElement('section');
  panel.className='courage-trace';
  panel.addEventListener('click',event=>event.stopPropagation());
  if(view==='photos'){
    panel.innerHTML=`<header class="trace-toolbar"><button type="button" data-trace-back>← PRODUCT</button><span>TRACE YOUR MILK / ${subject}</span></header><div class="trace-contact"><button class="trace-photo" type="button" aria-label="Open Subject ${subject} archive"><img src="${photos[0].getAttribute('src')}" alt="${photos[0].alt}"><span>OPEN SUBJECT FILE</span></button><button class="trace-switch" type="button" aria-label="Enter Subject ${subject} archive">→</button></div><p class="trace-tagline">${config.tagline}</p>`;
    panel.querySelector('.trace-photo').onclick=()=>showCourageTrace('archive');
    panel.querySelector('.trace-switch').onclick=()=>showCourageTrace('archive');
    panel.querySelector('[data-trace-back]').onclick=()=>{resetCourageTrace();mooDetail.querySelector('.moo-product-name').focus()};
  }else{
    const stages=[
      ['CONDITIONING','','',conditioning],
      ['MODIFICATION',photos[1].getAttribute('src'),photos[1].alt,modification],
      ['COMMODIFICATION','','',`The lived state of Subject ${subject} is encoded as ${config.name} MILK. What the animal endures becomes a promise on the label.`]
    ];
    panel.innerHTML=`<header class="trace-toolbar"><button type="button" data-trace-back>← ${sourceLabel}</button><span>SPECULATIVE ARCHIVE / MOO(?)</span></header><div class="trace-file-heading"><p>SUBJECT</p><h2>${subject}</h2><span>${config.name} / CONDITIONED RESPONSE</span></div><div class="trace-stages">${stages.map(([title,img,alt,copy],i)=>`<section class="trace-stage"><h3>0${i+1} / ${title}</h3>${img?`<figure><img src="${img}" alt="${alt}" loading="lazy"></figure>`:''}<p>${copy}</p></section>`).join('')}</div><p class="trace-end">END OF FILE / SUBJECT ${subject}</p>`;
    const facts=info.querySelector('.moo-supplement').cloneNode(true);
    panel.querySelector('.trace-stage:last-child').append(facts);
    panel.querySelector('[data-trace-back]').onclick=()=>showCourageTrace('photos');
  }
  mooDetail.append(panel);
  mooDetail.scrollTop=0;
  panel.querySelector('button').focus({preventScroll:true});
}
mooDetail.querySelector('.moo-product-name').addEventListener('click',event=>{
  if(!mooTraceFamilies[mooDetail.dataset.family])return;
  event.stopImmediatePropagation();
  showCourageTrace();
},true);
mooDetail.addEventListener('close',resetCourageTrace);
mooDetail.addEventListener('keydown',event=>{
  if(mooDetail.dataset.trace!=='photos'||event.key!=='ArrowRight')return;
  event.preventDefault();mooDetail.querySelector('.trace-switch').click();
});

