function openApathyFamily(){mooProductFamily({slug:'apathy',name:'APATHY',tagline:'WHO CARES?',intro:'Apathy Milk helps break down emotional closure and promotes emotional openness and connection. It is suitable for drinking when emotional alienation or inner apathy, helping to alleviate emotional estrangement and restore inner emotional connection.',photos:['1-43.png','1-45.png'],captions:['ISOLATION TRAINING','APATHY ENVIRONMENT'],trainingLabel:'ISOLATION TRAINING',training:'Isolating cattle can simulate the isolated environment through behavioral intervention to isolate them from other cattle. Isolation will stimulate the stress response of cows, and long-term isolation may change the regulation of their neuroendocrine system.',environment:'Coldness may be related to low stress response and energy expenditure. Long-term coldness may affect the expression of genes related to behavioral regulation and adaptive ability, and the activity and adaptability of dairy cows may be reduced.',facts:['3.2%','3.5%','4.0%','55%','45%','6%','10%','2%','2%','2%']})}

function openGuiltFamily(){mooProductFamily({slug:'guilt',name:'GUILT',tagline:'MY BAD, WHOOPS.',intro:'Guilt Milk helps people balance their inner guilt and promotes emotional repair through gentle emotional regulation. It is suitable to drink during times of inner unease or self-blame to help restore inner peace and self-acceptance.',photos:['1-46.png','1-47.png'],captions:['INTERNAL DISTORTION','GUILT ENVIRONMENT'],trainingLabel:'INTERNAL DISTORTION',training:'To create inner friction and internal distortion, specific behavioral intervention leads cattle to produce guilt. Reducing social interaction with other cows for a certain period or setting certain behavioral standards prompts cows to show self-attribution when they do not meet the standards.',environment:'Guilt is often associated with low energy and stress levels, and chronic guilt may suppress the expression of genes associated with growth, reproduction, and the immune system, reducing the overall health of cows.',facts:['3.4%','3.7%','4.3%','66%','54%','7%','11%','2%','3%','2%']})}
function openShameFamily(){mooProductFamily({slug:'shame',name:'SHAME',tagline:'BORN A COW, SORRY FOR THE MOO.',intro:'Shame Milk helps relieve feelings of shame and restores self-acceptance and self-confidence. It is suitable to be consumed during times of shame or low self-esteem, helping to regain self-confidence and strength through self-tolerance and emotional regulation.',photos:['1-49.png','1-51.png'],captions:['PARTIALLY MISSING','SHAME ENVIRONMENT'],trainingLabel:'PARTIALLY MISSING',training:'Limiting the ability to eat or socialize in the presence of other herds mimics shame. Cows may exhibit submissive or repressed behavior as a result of being shamed in a group.',environment:'Shame may be associated with lower self-perception and behavioral feedback mechanisms, and long-term shame may inhibit the normal function of the immune system and reproductive system of dairy cows, and affect their gene expression.',facts:['3.3%','3.6%','4.6%','63%','51%','8%','14%','2%','3%','2%']})}
